from collections import Counter

def transform(grid):
    """Move the non-background figure down by one row, clipping at the edge."""
    h = len(grid)
    if not h:
        return []
    w = len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[background] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background and r + 1 < h:
                out[r + 1][c] = grid[r][c]
    return out
